const config = $('Configuration').first().json;
const tags = $input.first().json;

const tagList = Array.isArray(tags) ? tags : [];

if (tagList.length === 0) {
  return { error: 'No tags found in repository', current_tag: null, previous_tag: null };
}

let currentTag, previousTag;
if (config.tag === 'latest') {
  currentTag = tagList[0];
  previousTag = tagList[1] || null;
} else {
  const tagIndex = tagList.findIndex(t => t.name === config.tag);
  if (tagIndex === -1) {
    return { error: `Tag ${config.tag} not found`, current_tag: null, previous_tag: null };
  }
  currentTag = tagList[tagIndex];
  previousTag = tagList[tagIndex + 1] || null;
}

return {
  current_tag: currentTag.name,
  current_sha: currentTag.commit?.sha,
  previous_tag: previousTag?.name || null,
  previous_sha: previousTag?.commit?.sha || null,
  repo_owner: config.repo_owner,
  repo_name: config.repo_name
};

const tagInfo = $('Parse Tags').first().json;
const comparison = $input.first().json;
const commits = comparison.commits || [];

const categories = {
  feat: { title: '✨ Features', items: [] },
  fix: { title: '🐛 Bug Fixes', items: [] },
  docs: { title: '📚 Documentation', items: [] },
  chore: { title: '🔧 Maintenance', items: [] },
  refactor: { title: '♻️ Refactoring', items: [] },
  test: { title: '🧪 Tests', items: [] },
  other: { title: '📝 Other Changes', items: [] }
};

for (const commit of commits) {
  const message = commit.commit?.message?.split('\n')[0] || '';
  if (message.startsWith('Merge ') || message.startsWith('[n8n]')) continue;
  const match = message.match(/^(\w+)(\([^)]+\))?:\s*(.+)/);
  if (match) {
    const type = match[1].toLowerCase();
    const scope = match[2] || '';
    const desc = match[3];
    const category = categories[type] || categories.other;
    category.items.push(`- ${scope}${desc} (${commit.sha?.slice(0, 7)})`);
  } else {
    categories.other.items.push(`- ${message} (${commit.sha?.slice(0, 7)})`);
  }
}

let changelog = `# Release ${tagInfo.current_tag}\n\n`;
if (tagInfo.previous_tag) {
  changelog += `**Full Changelog**: ${tagInfo.previous_tag}...${tagInfo.current_tag}\n\n`;
}

for (const [key, cat] of Object.entries(categories)) {
  if (cat.items.length > 0) {
    changelog += `## ${cat.title}\n\n${cat.items.join('\n')}\n\n`;
  }
}

changelog += `---\n*Generated automatically by Doc Chain - Release workflow*`;

return {
  tag: tagInfo.current_tag,
  previous_tag: tagInfo.previous_tag,
  commit_count: commits.length,
  changelog: changelog,
  repo_owner: tagInfo.repo_owner,
  repo_name: tagInfo.repo_name
};

const release = $input.first().json;
const changelog = $('Generate Changelog').first().json;

return {
  status: 'success',
  release_url: release.html_url,
  tag: changelog.tag,
  commit_count: changelog.commit_count,
  message: `Release ${changelog.tag} created successfully`
};

return {
  status: 'error',
  message: $('Parse Tags').first().json.error || 'No valid tags found',
  tag: null
};
